def euclidean_algorithm(x, y):
    """
    Finds the euclidean of two numbers
    :param x: First number
    :param y: Second number
    :return: Returns the euclidean of two given numbers i.e. x and y
    """
    if x == 0:
        return y
    return euclidean_algorithm(y % x, x)

